package com.twelvemonkeys.image;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import javax.imageio.ImageIO;
import java.awt.image.BufferedImage;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.*;

public class IndexImageMainTests {

    @Test
    void testMainGeneratesOutputFromSimpleInput(@TempDir Path tempDir) throws Exception {
        // Create a tiny input image (2x2) with distinct colors
        BufferedImage input = new BufferedImage(2, 2, BufferedImage.TYPE_INT_RGB);
        input.setRGB(0, 0, 0xFF0000); // red
        input.setRGB(1, 0, 0x00FF00); // green
        input.setRGB(0, 1, 0x0000FF); // blue
        input.setRGB(1, 1, 0xFFFFFF); // white

        Path inputPath = tempDir.resolve("input.png");
        ImageIO.write(input, "png", inputPath.toFile());

        Path outputPath = tempDir.resolve("output.png");

        // Run the main with input and output paths
        String[] args = new String[] { inputPath.toString(), outputPath.toString() };
        IndexImage.main(args);

        // Verify output was produced and is readable
        assertTrue(outputPath.toFile().exists(), "Output file should be created");
        BufferedImage output = ImageIO.read(outputPath.toFile());
        assertNotNull(output, "Output image should be readable");
    }

    @Test
    void testSpeedTestFlagDoesNotCrash(@TempDir Path tempDir) throws Exception {
        // Create a small input image
        BufferedImage input = new BufferedImage(4, 4, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                input.setRGB(x, y, ((x * 60) << 16) | ((y * 60) << 8) | 128);
            }
        }

        Path inputPath = tempDir.resolve("input_speed.png");
        ImageIO.write(input, "png", inputPath.toFile());

        Path outputPath = tempDir.resolve("output_speed.png");

        // Invoke with speedtest flag to exercise additional code paths without relying on external timing facilities
        String[] args = new String[] { "-s", "2", inputPath.toString(), outputPath.toString() };
        IndexImage.main(args);

        // Output should still be produced and readable
        assertTrue(outputPath.toFile().exists(), "Output file should be created under speedtest");
        BufferedImage output = ImageIO.read(outputPath.toFile());
        assertNotNull(output, "Output image should be readable under speedtest");
    }
}

