package com.twelvemonkeys.image;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import javax.imageio.ImageIO;
import java.awt.Color;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;

class IndexImageMainTests {
    @Test
    void unknownOptionIsConsumedWithoutActivatingAnotherMode(@TempDir Path tempDir) throws IOException {
        Path input = tempDir.resolve("input.png");
        Path output = tempDir.resolve("output.png");

        BufferedImage source = new BufferedImage(2, 2, BufferedImage.TYPE_INT_RGB);
        for (int y = 0; y < source.getHeight(); y++) {
            for (int x = 0; x < source.getWidth(); x++) {
                source.setRGB(x, y, Color.RED.getRGB());
            }
        }
        ImageIO.write(source, "png", input.toFile());

        IndexImage.main(new String[]{"-unknown", input.toString(), output.toString()});

        assertEquals(true, Files.exists(output));
        BufferedImage converted = ImageIO.read(output.toFile());
        assertNotNull(converted);

        for (int y = 0; y < converted.getHeight(); y++) {
            for (int x = 0; x < converted.getWidth(); x++) {
                assertEquals(Color.RED.getRGB(), converted.getRGB(x, y));
            }
        }
    }
}

