    @Test
    void testReadThrowsIIOExceptionForTooManyBitPlanes() throws Exception {
        // Build a PCX header that triggers the "Unsupported number of bit planes for PCX" path:
        // - bitsPerPixel: 1 (to encourage IndexColorModel path)
        // - channels: 9 (trigger the 9+ planes error)
        final int headerSize = PCX.HEADER_SIZE;
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        byte[] header = new byte[headerSize];
        header[0] = PCX.MAGIC;
        header[1] = PCX.VERSION_3;
        header[2] = PCX.COMPRESSION_NONE;
        header[3] = 1; // bitsPerPixel = 1
        // XStart = 0
        header[4] = 0;
        header[5] = 0;
        // YStart = 0
        header[6] = 0;
        header[7] = 0;
        // XEnd = 1 -> width = 2
        header[8] = 1;
        header[9] = 0;
        // YEnd = 0 -> height = 1
        header[10] = 0;
        header[11] = 0;
        // hdpi, vdpi
        header[12] = 0;
        header[13] = 0;
        // palette (48 bytes) - leave as zeros
        // reserved
        header[64] = 0;
        // channels = 9 (trigger error)
        header[65] = 9;
        // bytesPerLine
        header[66] = 2; header[67] = 0;
        // paletteType
        header[68] = 0; header[69] = 0;
        // rest zeros
        for (int i = 72; i < headerSize; i++) {
            header[i] = 0;
        }

        baos.write(header);

        // No need to provide image data; the reader should throw during processing
        ImageInputStream stream = ImageIO.createImageInputStream(new ByteArrayInputStream(baos.toByteArray()));
        PCXImageReaderSpi spi = new PCXImageReaderSpi();
        PCXImageReader reader = new PCXImageReader(spi);
        reader.setInput(stream);

        ImageReadParam param = reader.getDefaultReadParam();
        param.setDestinationType(reader.getImageTypes(0).next());

        assertThrows(IIOException.class, () -> {
            reader.read(0, param);
        }, "Expected IIOException due to unsupported number of bit planes (channels > 8)");
    }
}

