package com.twelvemonkeys.imageio.plugins.psd;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Tests for the PSDImageReader.main entry point behavior.
 * These tests exercise the command line parsing and exit behavior without requiring actual PSD files.
 */
public class PSDImageReaderMainTests {

    // Exception used to trap System.exit(code) calls from the tested code.
    private static class ExitTrappedException extends SecurityException {
        private final int status;

        ExitTrappedException(int status) {
            super("Exit code: " + status);
            this.status = status;
        }

        int getStatus() {
            return status;
        }
    }

    // Security manager that intercepts System.exit calls made by PSDImageReader.main
    private static class ExitTrappingSecurityManager extends SecurityManager {
        @Override
        public void checkPermission(java.security.Permission perm) {
            // Allow all other permissions
        }

        @Override
        public void checkExit(int status) {
            throw new ExitTrappedException(status);
        }
    }

    @Test
    void testUnknownOptionExitsWithCodeOne() {
        SecurityManager original = System.getSecurityManager();
        try {
            System.setSecurityManager(new ExitTrappingSecurityManager());
            ExitTrappedException ex = assertThrows(ExitTrappedException.class, () -> {
                PSDImageReader.main(new String[]{ "-x" });
            });
            assertEquals(1, ex.getStatus(), "Unknown option should trigger exit code 1");
        } finally {
            System.setSecurityManager(original);
        }
    }

    @Test
    void testMainWithOnlyOptionsDoesNotExit() {
        // Providing only valid options (no files) triggers an ArrayIndexOutOfBoundsException due to missing image file argument
        assertThrows(ArrayIndexOutOfBoundsException.class, () -> PSDImageReader.main(new String[]{ "-s", "2" }));
    }
}

