package com.twelvemonkeys.imageio.plugins.tiff;

import org.junit.jupiter.api.Test;

import javax.imageio.ImageIO;
import javax.imageio.ImageReadParam;
import javax.imageio.ImageTypeSpecifier;
import javax.imageio.stream.ImageInputStream;
import java.awt.image.DataBuffer;
import java.awt.image.IndexColorModel;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataOutputStream;
import java.io.IOException;

import static org.junit.jupiter.api.Assertions.*;

public class TIFFImageReaderGetRawImageTypeTests {

    @Test
    public void testGetRawImageType_1bitWhiteIsZeroIndexed() throws Exception {
        byte[] tiffBytes = buildMinimal1BitWhiteIsZeroTIFF();
        ImageInputStream iis = ImageIO.createImageInputStream(new ByteArrayInputStream(tiffBytes));

        TIFFImageReaderSpi spi = new TIFFImageReaderSpi();
        TIFFImageReader reader = new TIFFImageReader(spi);
        reader.setInput(iis, true, true);

        ImageTypeSpecifier type = reader.getRawImageType(0);
        assertNotNull(type, "Raw ImageTypeSpecifier should not be null");

        // Expect an indexed color model for 1-bit grayscale (WhiteIsZero)
        assertTrue(type.getColorModel() instanceof IndexColorModel, "Expected IndexColorModel for 1-bit WhiteIsZero");
        IndexColorModel icm = (IndexColorModel) type.getColorModel();

        // Two colors in the palette
        assertEquals(2, icm.getMapSize(), "Palette size for 1-bit should be 2");

        // Bits per sample should be 1
        assertEquals(1, type.getBitsPerBand(0), "Bits per sample should be 1 for 1-bit image");
        // Data type should be byte
        assertEquals(DataBuffer.TYPE_BYTE, type.getSampleModel().getDataType(), "Data type should be byte for 1-bit image");

        // Palette should map index 0 -> white and index 1 -> black
        // 0 -> 0xFFFFFFFF (white with opaque alpha), 1 -> 0xFF000000 (black with opaque alpha)
        assertEquals(0xFFFFFFFF, icm.getRGB(0), "Index 0 should map to white color");
        assertEquals(0xFF000000, icm.getRGB(1), "Index 1 should map to black color");
    }

    private static byte[] buildMinimal1BitWhiteIsZeroTIFF() throws IOException {
        // Minimal TIFF (little-endian) with:
        // - 1x1 image
        // - BitsPerSample = 1
        // - PhotometricInterpretation = WhiteIsZero (0)
        // - SamplesPerPixel = 1
        // - No ExtraSamples, no ICCProfile
        // - ImageWidth = 1, ImageLength = 1

        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(baos);

        // TIFF header
        out.write('I');
        out.write('I');
        writeLEShort(out, 42);    // TIFF identifier
        writeLEInt(out, 8);       // Offset to first IFD (byte offset 8)

        // IFD (at offset 8)
        writeLEShort(out, 5);     // Number of directory entries

        // Entry 1: ImageWidth (tag 256), type LONG (4), count 1, value 1
        writeLEShort(out, 256);   // Tag
        writeLEShort(out, 4);     // Type LONG
        writeLEInt(out, 1);       // Count
        writeLEInt(out, 1);       // Value

        // Entry 2: ImageLength (tag 257), type LONG (4), count 1, value 1
        writeLEShort(out, 257);
        writeLEShort(out, 4);
        writeLEInt(out, 1);
        writeLEInt(out, 1);

        // Entry 3: BitsPerSample (tag 258), type SHORT (3), count 1, value 1
        writeLEShort(out, 258);
        writeLEShort(out, 3);
        writeLEInt(out, 1);
        writeLEInt(out, 1);

        // Entry 4: PhotometricInterpretation (tag 262), type SHORT (3), count 1, value 0 (WhiteIsZero)
        writeLEShort(out, 262);
        writeLEShort(out, 3);
        writeLEInt(out, 1);
        writeLEInt(out, 0);

        // Entry 5: SamplesPerPixel (tag 277), type SHORT (3), count 1, value 1
        writeLEShort(out, 277);
        writeLEShort(out, 3);
        writeLEInt(out, 1);
        writeLEInt(out, 1);

        // Next IFD offset: 0 (no more IFDs)
        writeLEInt(out, 0);

        out.flush();
        return baos.toByteArray();
    }

    private static void writeLEShort(DataOutputStream out, int v) throws IOException {
        out.write(v & 0xFF);
        out.write((v >> 8) & 0xFF);
    }

    private static void writeLEInt(DataOutputStream out, int v) throws IOException {
        out.write(v & 0xFF);
        out.write((v >> 8) & 0xFF);
        out.write((v >> 16) & 0xFF);
        out.write((v >> 24) & 0xFF);
    }
}

