package com.twelvemonkeys.imageio.plugins.webp.lossless;

import java.awt.image.BufferedImage;
import java.awt.image.WritableRaster;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class PredictorTransformApplyInverseTests {

    @Test
    public void testApplyInverseOnAllZeroRasterResultsInOpaqueBlack() {
        int width = 2;
        int height = 2;

        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_4BYTE_ABGR);
        WritableRaster raster = image.getRaster();

        // Initialize all pixels to zero (RGBA all zero)
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                byte[] pixel = new byte[] {0, 0, 0, 0};
                raster.setDataElements(x, y, pixel);
            }
        }

        PredictorTransform transform = new PredictorTransform(raster, (byte) 0);
        transform.applyInverse(raster);

        // All pixels should end up as opaque black (R=0, G=0, B=0, A=255)
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                byte[] rgba = new byte[4];
                raster.getDataElements(x, y, rgba);
                int r = rgba[0] & 0xff;
                int g = rgba[1] & 0xff;
                int b = rgba[2] & 0xff;
                int a = rgba[3] & 0xff;

                assertEquals(0, r, "Red channel not zero at (" + x + "," + y + ")");
                assertEquals(0, g, "Green channel not zero at (" + x + "," + y + ")");
                assertEquals(0, b, "Blue channel not zero at (" + x + "," + y + ")");
                assertEquals(255, a, "Alpha channel not 255 (opaque) at (" + x + "," + y + ")");
            }
        }
    }

    @Test
    public void testApplyInverseTopLeftRetainsInitialColorAndUpdatesAlphaAccordingToMask() {
        int width = 2;
        int height = 2;

        BufferedImage image = new BufferedImage(width, height, BufferedImage.TYPE_4BYTE_ABGR);
        WritableRaster raster = image.getRaster();

        // Initialize all pixels to zero
        for (int y = 0; y < height; y++) {
            for (int x = 0; x < width; x++) {
                raster.setDataElements(x, y, new byte[]{0, 0, 0, 0});
            }
        }

        // Set top-left pixel to a known color and alpha
        // R=10, G=20, B=30, A=200
        raster.setDataElements(0, 0, new byte[]{10, 20, 30, (byte) 200});

        PredictorTransform transform = new PredictorTransform(raster, (byte) 0);
        transform.applyInverse(raster);

        byte[] topLeft = new byte[4];
        raster.getDataElements(0, 0, topLeft);
        int r = topLeft[0] & 0xff;
        int g = topLeft[1] & 0xff;
        int b = topLeft[2] & 0xff;
        int a = topLeft[3] & 0xff;

        assertEquals(10, r, "Top-left Red channel changed unexpectedly");
        assertEquals(20, g, "Top-left Green channel changed unexpectedly");
        assertEquals(30, b, "Top-left Blue channel changed unexpectedly");

        // Alpha updated by adding 0xff (255) with wraparound on 8-bit value:
        // (200 + 255) mod 256 = 199
        int expectedAlpha = ((200 & 0xff) + 0xff) & 0xff;
        assertEquals(expectedAlpha, a, "Top-left Alpha did not wrap as expected");
    }
}

