            SubBlock block = macroBlock.getSubBlock(plane, rightBoundary ? 1 : 0, y);
            int[][] pixels = pixels(block);
            int last = pixels.length - 1;

            for (int i = 0; i < pixels.length; i++) {
                if (rightBoundary) {
                    pixels[i][last] = value;
                }
                else {
                    pixels[i][0] = value;
                }
            }
        }
    }

    private static int pixel(MacroBlock macroBlock, SubBlock.Plane plane,
                             int blockX, int blockY, int row, int column) throws Exception {
