    }

    private static int[][] pixels(SubBlock subBlock) throws Exception {
        Field field = SubBlock.class.getDeclaredField("dest");
        field.setAccessible(true);

        int[][] pixels = (int[][]) field.get(subBlock);
        if (pixels == null) {
            pixels = new int[4][4];
            field.set(subBlock, pixels);
        }

        return pixels;
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
