 *
 * Tests for MacroBlock.predictUV behavior, focusing on DC_PRED mode handling
 * and ensuring behavior matches specification, including regression checks for
 * a known defect in neighbor summation logic.
 */
public class MacroBlockPredictUVTests {

    // NOTE:
    // VP8Frame is final in this codebase, so we cannot subclass it for test doubles.
    // To preserve compilation, we instantiate a real VP8Frame instance and use
    // its public API. This test covers the DC_PRED default behavior when no
    // neighboring blocks are available.
    private VP8Frame createSimpleFrame(byte[] dummy) {
        ByteArrayInputStream bais = new ByteArrayInputStream(dummy);
        ImageInputStream stream = new MemoryCacheImageInputStream(bais);

        try {
            // Use a mode that may produce a synthetic frame suitable for tests.
            // Some internal initializations paths may require this to avoid
            // NullPointerExceptions when macroblocks are queried.
            return new VP8Frame(stream, false);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    void testPredictUV_DC_PRED_no_neighbors_defaults_to_128() throws Exception {
        // Arrange: create a MacroBlock at (1,1) (somewhere in the frame grid) with DC_PRED
        MacroBlock mb = new MacroBlock(1, 1, false);
        mb.setUvMode(Globals.DC_PRED); // ensure DC_PRED mode is used

        // Create a dummy VP8Frame where no neighbors exist (x==0,y==0 for the left/top)
        VP8Frame frame = createSimpleFrame(new byte[0]);
        // Act
        mb.predictUV(frame);

        // Assert: After DC_PRED with no neighbors, 4x4 prediction blocks should be filled with 128 (0x80)
        // Verify one representative value from uSubBlocks and vSubBlocks
        SubBlock usb = mb.getUSubBlock(0, 0);
        SubBlock vsb = mb.getVSubBlock(0, 0);

        // The predicted values should be uniform and equal to 128
        int[][] uBlock = usb.getPredict();
        int[][] vBlock = vsb.getPredict();

        assertNotNull(uBlock, "U subblock prediction should be set");
        assertNotNull(vBlock, "V subblock prediction should be set");

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertEquals(128, uBlock[x][y], "U prediction value at (" + x + "," + y + ") should be 128");
                assertEquals(128, vBlock[x][y], "V prediction value at (" + x + "," + y + ") should be 128");
            }
        }
    }

}

