        if (uPredBlock != null && vPredBlock != null) {
            int[][] uPred = uPredBlock.getPredict();
            int[][] vPred = vPredBlock.getPredict();

            boolean anyNonZero = false;
            outer:
            for (int y = 0; y < 4; y++) {
                for (int x = 0; x < 4; x++) {
                    if (uPred[x][y] != 0 || vPred[x][y] != 0) {
                        anyNonZero = true;
                        break outer;
                    }
                }
            }
            assertTrue(anyNonZero, "H_PRED should produce non-zero predictions from left neighbors when available");
