package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.jupiter.api.Assertions.assertEquals;

class MacroBlockPredictUVTests {
    @Test
    void verticalPredictionUsesTheCorrespondingAboveChrominanceSubblock() throws Exception {
        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])),
                false
        );

        MacroBlock[][] macroBlocks = new MacroBlock[6][6];
        for (int y = 0; y < macroBlocks.length; y++) {
            for (int x = 0; x < macroBlocks[y].length; x++) {
                macroBlocks[y][x] = new MacroBlock(x, y, false);

                for (int subBlockX = 0; subBlockX < 2; subBlockX++) {
                    for (int subBlockY = 0; subBlockY < 2; subBlockY++) {
                        setRecon(macroBlocks[y][x].uSubBlocks[subBlockX][subBlockY], 0);
                        setRecon(macroBlocks[y][x].vSubBlocks[subBlockX][subBlockY], 0);
                    }
                }
            }
        }

        setField(frame, "macroBlocks", macroBlocks);
        setField(frame, "macroBlockRows", 6);
        setField(frame, "macroBlockCols", 6);

        MacroBlock target = macroBlocks[3][3];
        setField(target, "uvMode", Globals.V_PRED);

        MacroBlock above = macroBlocks[2][3];
        int[] uValues = {17, 93};
        int[] vValues = {31, 111};

        for (int x = 0; x < 2; x++) {
            for (int planeY = 0; planeY < 2; planeY++) {
                setRecon(above.uSubBlocks[x][planeY], uValues[x]);
                setRecon(above.vSubBlocks[x][planeY], vValues[x]);
            }
        }

        target.predictUV(frame);

        for (int y = 0; y < 2; y++) {
            for (int x = 0; x < 2; x++) {
                assertUniform(target.uSubBlocks[x][y], uValues[x]);
                assertUniform(target.vSubBlocks[x][y], vValues[x]);
            }
        }
    }

    private static void setRecon(SubBlock subBlock, int value) throws Exception {
        int[][] recon = new int[4][4];
        for (int[] row : recon) {
            Arrays.fill(row, value);
        }
        setField(subBlock, "recon", recon);
    }

    private static void assertUniform(SubBlock subBlock, int expected) throws Exception {
        int[][] prediction = (int[][]) getField(subBlock, "predict");
        for (int[] row : prediction) {
            for (int value : row) {
                assertEquals(expected, value);
            }
        }
    }

    private static Object getField(Object target, String name) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        return field.get(target);
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
}

