package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class MacroBlockPredictYTests {

    // Helper to invoke MacroBlock.predictY via reflection, passing a VP8Frame reference.
    // We pass null to simulate "no frame" / no-neighbor scenario.
    private void predictYWithFrame(MacroBlock mb, Object frame) throws Exception {
        Class<?> frameClass = Class.forName("com.twelvemonkeys.imageio.plugins.webp.vp8.VP8Frame");
        java.lang.reflect.Method method = MacroBlock.class.getMethod("predictY", frameClass);
        Object toPass = frame;
        method.invoke(mb, toPass);
    }

    // Helper to create a MacroBlock with a given Y mode.
    private MacroBlock makeMacroBlock(int x, int y, int yMode) throws java.io.IOException {
        MacroBlock mb = new MacroBlock(x, y, false);
        mb.setYMode(yMode);
        return mb;
    }

    @Test
    public void testDcPred_NoNeighborsDefaultsTo128() throws Exception {
        // Create a macroblock at coordinates (1,1) with DC_PRED
        MacroBlock mb = makeMacroBlock(1, 1, Globals.DC_PRED);

        // Simulate a frame as null to test no-neighbor behavior
        predictYWithFrame(mb, null);

        // Verify that all four-by-four Y-subblocks of mb are filled with 128
        for (int sy = 0; sy < 4; sy++) {
            for (int sx = 0; sx < 4; sx++) {
                SubBlock sb = mb.getYSubBlock(sx, sy);
                int[][] recon = sb.getReconPredict(Globals.B_DC_PRED, false);
                for (int i = 0; i < 4; i++) {
                    for (int j = 0; j < 4; j++) {
                        assertEquals(128, recon[i][j], "Pixel not initialized to 128 in DC_PRED with no neighbors");
                    }
                }
            }
        }
