package com.twelvemonkeys.imageio.plugins.webp.vp8;

import org.junit.jupiter.api.Test;

import javax.imageio.stream.MemoryCacheImageInputStream;
import java.io.ByteArrayInputStream;
import java.lang.reflect.Field;

import static org.junit.jupiter.api.Assertions.assertEquals;

class SubBlockPredictTests {
    @Test
    void dcPredictionAveragesTheFourTopAndFourLeftSamples() throws Exception {
        VP8Frame frame = new VP8Frame(
                new MemoryCacheImageInputStream(new ByteArrayInputStream(new byte[0])),
                false
        );

        MacroBlock[][] macroBlocks = new MacroBlock[1][1];
        macroBlocks[0][0] = new MacroBlock(0, 0, false);

        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                macroBlocks[0][0].getYSubBlock(x, y)
                        .setPredict(filledPrediction(0));
            }
        }

        setField(frame, "macroBlocks", macroBlocks);
        setField(frame, "macroBlockRows", 1);
        setField(frame, "macroBlockCols", 1);

        int[] topSamples = {10, 20, 30, 40};
        int[] leftSamples = {50, 60, 70, 80};
        int[] zeros = {0, 0, 0, 0};

        macroBlocks[0][0].getYSubBlock(1, 0)
                .setPredict(predictionWithRightAndBottomEdges(zeros, topSamples));
        macroBlocks[0][0].getYSubBlock(0, 1)
                .setPredict(predictionWithRightAndBottomEdges(leftSamples, zeros));

        SubBlock current = macroBlocks[0][0].getYSubBlock(1, 1);
        current.setMode(Globals.B_DC_PRED);
        current.predict(frame);

        int[][] prediction = current.getPredict();
        int expected = (10 + 20 + 30 + 40 + 50 + 60 + 70 + 80 + 4) >> 3;

        for (int y = 0; y < 4; y++) {
            for (int x = 0; x < 4; x++) {
                assertEquals(expected, prediction[x][y]);
            }
        }
    }

    private static int[][] filledPrediction(int value) {
        int[][] prediction = new int[4][4];
        for (int x = 0; x < 4; x++) {
            for (int y = 0; y < 4; y++) {
                prediction[x][y] = value;
            }
        }
        return prediction;
    }

    private static int[][] predictionWithRightAndBottomEdges(int[] right, int[] bottom) {
        int[][] prediction = filledPrediction(0);

        for (int y = 0; y < right.length; y++) {
            prediction[3][y] = right[y];
        }

        for (int x = 0; x < bottom.length; x++) {
            prediction[x][3] = bottom[x];
        }

        return prediction;
    }

    private static void setField(Object target, String name, Object value) throws Exception {
        Field field = target.getClass().getDeclaredField(name);
        field.setAccessible(true);
        field.set(target, value);
    }
}

