import static org.junit.jupiter.api.Assertions.assertFalse;

public class VP8FrameDecodeTests {

    @Test
    public void testDecodeReturnsFalseForNonIntraFrame() throws IOException {
        // Arrange: construct a minimal VP8Frame with a first byte that indicates non-intra frame
        // frameType is determined by the least significant bit (bit 0).
        // We set it to 1 to simulate a non-intra (inter) frame.
        byte[] data = new byte[] { (byte) 0x01 }; // LSB = 1 -> frameType != 0

        ImageInputStream stream = new MemoryCacheImageInputStream(new ByteArrayInputStream(data));
        VP8Frame frame = new VP8Frame(stream, false);

        // Use a tiny, valid BufferedImage raster as a placeholder; decode should early-return before using it.
        BufferedImage img = new BufferedImage(2, 2, BufferedImage.TYPE_INT_RGB);
        WritableRaster raster = img.getRaster();

        ImageReadParam param = new ImageReadParam();

        // Act
        boolean result = frame.decode(raster, param);

        // Assert: For non-intra frames (frameType != 0) decode should return false.
        assertFalse(result, "decode should return false for non-intra frames (frameType != 0)");
    }
}

